import functools


@functools.cache
def word_score(word):
    print(f"scoring {word}")
    return sum(ord(ch) - ord("a") + 1 for ch in word)


digits = [4, 0, 7, 2]
number = functools.reduce(lambda a, b: a * 10 + b, digits)
print("Number:", number)

from_hex = functools.partial(int, base=16)
print("ff ->", from_hex("ff"))

for word in ["cab", "bad", "cab"]:
    print(f"{word} = {word_score(word)}")
